// Match only names generated by the local test suites, including older labels.
const uuid = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
const contract = new RegExp(`^Fixture de contrato [·-] sem envio externo ${uuid}$`, 'i');
const phase51 = new RegExp(`^Phase 5\\.1 fixture ${uuid}$`, 'i');
const providerSuite = new RegExp(`^(MOCK Sandbox|META Cloud|Z-API) ${uuid}$`);
export function isWhatsAppTestFixture(name) {
  return (
    contract.test(name) ||
    phase51.test(name) ||
    providerSuite.test(name) ||
    /^(Conta sem provedor|Sandbox) \d{13}$/.test(name)
  );
}
